import{_ as t}from"./chunks/difficulty_easy.76S4H_Nf.js";import{_ as i}from"./chunks/remote_control.ss1psCxn.js";import{_ as a}from"./chunks/altitude_icon.CQEDErje.js";import{_ as l}from"./chunks/altitude_mc.Gg9aQs-s.js";import{_ as o,c as r,o as n,al as s}from"./chunks/framework.D8UyiDWg.js";const k=JSON.parse('{"title":"Altitude Cruise Mode (Multicopter)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/flight_modes_mc/altitude_cruise.md","filePath":"zh/flight_modes_mc/altitude_cruise.md"}'),d={name:"zh/flight_modes_mc/altitude_cruise.md"};function h(c,e,m,u,f,_){return n(),r("div",null,e[0]||(e[0]=[s('<h1 id="altitude-cruise-mode-multicopter" tabindex="-1">Altitude Cruise Mode (Multicopter) <a class="header-anchor" href="#altitude-cruise-mode-multicopter" aria-label="Permalink to &quot;Altitude Cruise Mode (Multicopter)&quot;">​</a></h1><p><img src="'+t+'" title="Easy to fly" width="30px"> <img src="'+i+'" title="Manual/Remote control required" width="30px"> <img src="'+a+'" title="Altitude required (e.g. Baro, Rangefinder)" width="30px"></p><p><em>Altitude Cruise mode</em> is a <em>relatively</em> easy-to-fly manual control mode in which roll and pitch sticks control vehicle movement in the left-right and forward-back directions (relative to the &quot;front&quot; of the vehicle), yaw stick controls rate of rotation over the horizontal plane, and throttle controls speed of ascent-descent.</p><p>When the sticks are released/centered the vehicle will keep the current tilt and heading angle and maintain the current <em>altitude</em>. If moving in the horizontal plane the vehicle will accelerate until the wind resistance equals the acceleration caused by the set tilt angle. The vehicle will then continue to move with a constant velocity (unlike for Altitude mode, in which the vehicle will eventually slow down and stop). If the wind blows the aircraft will drift in the direction of the wind even if flying perfectly level.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><em>Altitude Cruise mode</em> is intended for long distance flights where the same tilt angle is kept for a long period of time. It is just like <a href="./../flight_modes_mc/altitude.html">Altitude</a> mode but does not go back to level tilt when the sticks are released.</p></div><p>The diagram below shows the mode behaviour visually (for a <a href="./../getting_started/rc_transmitter_receiver.html#transmitter_modes">mode 2 transmitter</a>).</p><p><img src="'+l+'" alt="Altitude Control MC - Mode2 RC Controller"></p><h2 id="技术总结" tabindex="-1">技术总结 <a class="header-anchor" href="#技术总结" aria-label="Permalink to &quot;技术总结&quot;">​</a></h2><p>A manual mode that is similar to <a href="./../flight_modes_mc/altitude.html">Altitude mode</a> but with different interpretation of roll and pitch sticks.</p><ul><li>Centered sticks: <ul><li>Roll/Pitch sticks: the current tilt is kept.</li><li>Yaw: the current heading is kept.</li><li>Throttle (~50%) holds current altitude.</li></ul></li><li>外部中心： <ul><li>Roll/Pitch sticks control the rate of change of the tilt angle, resulting in corresponding left-right and forward-back movement. A maximum stick deflection results in a tilting rate setpoint to go from level to max tilt within 0.5 seconds.</li><li>Yaw stick deflection rotates the tilt angle either left or right, causing the vehicle to change course. It is <em>not</em> causing a direct rotation around the body yaw axis like in <a href="./../flight_modes_mc/acro.html">Acro mode</a>.</li><li>油门摇杆以预定的最大速率（和其他轴上的移动速度）控制上升速度。</li></ul></li><li>起飞： <ul><li>降落时，如果将油门杆抬高至 62.5%（从油门杆最低开始的整个范围），无人机将起飞。</li></ul></li><li>Manual control input is required (such as RC control, joystick) to enter this mode. Other than in all other manual modes, it&#39;s though possible to disable the manual control loss failsafe by setting the corresponding flag in <a href="./../advanced_config/parameter_reference.html#COM_RCL_EXCEPT">COM_RCL_EXCEPT</a>. In that case the current altitude, tilt and heading are kept until the manual control link is regained or the mode is exited. It is highly recommended to only disable the manual control loss failsafe for this mode if there is a stable data link connection to the vehicle at all times, and to enable the data link loss failsafe through <a href="./../advanced_config/parameter_reference.html#NAV_DLL_ACT">NAV_DLL_ACT</a>.</li></ul><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h2><p>Most of the relevant parameters are already covered in the corresponding section in the <a href="./../flight_modes_mc/altitude.html">Altitude mode</a>. Here a list of parameters of particular importance for Altitude Cruise.</p><table tabindex="0"><thead><tr><th>参数</th><th>描述</th></tr></thead><tbody><tr><td><a id="COM_RCL_EXCEPT"></a><a href="./../advanced_config/parameter_reference.html#COM_RCL_EXCEPT">COM_RCL_EXCEPT</a></td><td>The manual control failsafe can be disabled for Altitude Cruise by setting the corresponding bit in this parameter.</td></tr><tr><td><a id="NAV_DLL_ACT"></a><a href="./../advanced_config/parameter_reference.html#NAV_DLL_ACT">NAV_DLL_ACT</a></td><td>Data link lost failsafe action. Recommended to set if the manual control failsafe is disabled to avoid fly-aways.</td></tr><tr><td><a id="MPC_MAN_TILT_MAX"></a><a href="./../advanced_config/parameter_reference.html#MPC_MAN_TILT_MAX">MPC_MAN_TILT_MAX</a></td><td>The maximum tilt angle the vehicle will go to. At max stick deflection, it will take 0.5 seconds from level flight to this tilt angle.</td></tr></tbody></table>',13)]))}const b=o(d,[["render",h]]);export{k as __pageData,b as default};
